def _joints_to_hand_state(joints, is_active, image_points):
    '''Convert a list of JointPose objects to a HandState proto message.

    Pinch is measured from the same joints, checked against the detection\'s
    ``image_points`` when given (see ``pinch_strengths``), and sent alongside
    them, so a consumer gets gesture state without having to re-derive it from
    the skeleton. It is left unset in the two cases the proto reserves for "no
    pinch data": an inactive hand, whose joints are placeholders, and an active
    hand whose skeleton cannot support a measurement. Writing a zeroed
    PinchState in either case would read as a deliberate "not pinching" and
    fire a release the hand never performed.
    '''
    state = hand_tracking_pb2.HandState(is_active = is_active)
    strengths = pinch_strengths(joints, image_points) if is_active else None
    if strengths is not None:
        state.pinch.index = strengths.index
        state.pinch.middle = strengths.middle
        state.pinch.ring = strengths.ring
        state.pinch.little = strengths.little
    for jp in joints:
        joint = hand_tracking_pb2.HandJoint(pose = hand_tracking_pb2.Pose(orientation = hand_tracking_pb2.Quaternion(x = jp.orientation.x, y = jp.orientation.y, z = jp.orientation.z, w = jp.orientation.w), position = hand_tracking_pb2.Vector3(x = jp.position.x, y = jp.position.y, z = jp.position.z)), radius = jp.radius)
        state.joints.append(joint)
    return state

