def _resolve_handedness(hands):
    '''Per-hand user-perspective \'Left\'/\'Right\' label.

    The Tasks HandLandmarker already reports handedness from the user\'s
    perspective, so its labels pass straight through. They are NOT swapped: the
    legacy Solutions API documented labels as assuming a mirrored (selfie)
    image, and carrying that assumption over reversed every hand — colouring
    them backwards in the client and retargeting each with the opposite
    chirality, since ``retarget`` keys off this label.

    MediaPipe does occasionally collapse BOTH hands onto the same label; left
    uncorrected they route into one slot and one hand vanishes (the "only one
    hand shows" failure). In that case ignore the labels and split by wrist
    image-x instead: on the raw frame the hand detector is fed (see
    WebcamCapture), camera-left (smaller x) is the user\'s right hand, matching
    the X mirror in ``estimate_stage_position``.
    '''
    for h in hands:
        pass
    labels = []
    h = h
    if len(hands) == 2 and labels[0] == labels[1]:
        x0 = hands[0].image_landmarks[0][0] if hands[0].image_landmarks else 0.5
        x1 = hands[1].image_landmarks[0][0] if hands[1].image_landmarks else 0.5
        if x0 <= x1:
            return [
                'Right',
                'Left']
        return [
            'Left',
            'Right']
    return labels
    h = None


def _make_inactive_hand_state():
    '''Create an inactive HandState with 26 zeroed joints.'''
    state = hand_tracking_pb2.HandState(is_active = False)
    for _ in range(26):
        state.joints.append(hand_tracking_pb2.HandJoint(pose = hand_tracking_pb2.Pose(orientation = hand_tracking_pb2.Quaternion(x = 0, y = 0, z = 0, w = 1), position = hand_tracking_pb2.Vector3(x = 0, y = 0, z = 0)), radius = 0))
    return state

