def _mirror_head_orientation(orientation):
    '''Un-mirror the detected head orientation per the XRSIM_HEAD_MIRROR env var.

    Read per call (cheap) so the mode is picked up from the process environment
    the sidecar was spawned with; unknown values fall back to the default.
    '''
    if not os.environ.get('XRSIM_HEAD_MIRROR'):
        os.environ.get('XRSIM_HEAD_MIRROR')
    mode = _DEFAULT_HEAD_MIRROR.strip().lower()
    transform = _HEAD_MIRROR_TRANSFORMS.get(mode, _HEAD_MIRROR_TRANSFORMS[_DEFAULT_HEAD_MIRROR])
    (ox, oy, oz, ow) = orientation
    return transform(ox, oy, oz, ow)


def _apply_head_pose(frame, head_detection):
    '''Populate frame.head_pose from a head-pose result.

    Marks the payload inactive when no face was detected so the runtime falls
    back to WASD-only head control. Setting the message (even inactive) keeps
    has_head_pose() true, which distinguishes "head tracking on, no face this
    frame" from "head tracking off" (field left unset by the caller).
    '''
    if head_detection is not None and head_detection.is_active:
        (ox, oy, oz, ow) = head_detection.orientation
        frame.head_pose.is_active = True
        frame.head_pose.confidence = head_detection.confidence
        frame.head_pose.pose.position.x = 0
        frame.head_pose.pose.position.y = 0
        frame.head_pose.pose.position.z = 0
        (mx, my, mz, mw) = _mirror_head_orientation((ox, oy, oz, ow))
        frame.head_pose.pose.orientation.x = mx
        frame.head_pose.pose.orientation.y = my
        frame.head_pose.pose.orientation.z = mz
        frame.head_pose.pose.orientation.w = mw
        return None
    frame.head_pose.is_active = False


