        t_s = detection.timestamp_ms / 1000
        handedness_per_hand = resolved_handedness if resolved_handedness is not None else _resolve_handedness(detection.hands)
        for hand, handedness in zip(detection.hands, handedness_per_hand):
            if handedness is None:
                continue
            seen_hands.add(handedness)
            hand_prediction_s = 0 if no_prediction_labels is not None and handedness in no_prediction_labels else prediction_s
            hand_state = _hand_state_from_detection(hand, handedness, workspace, filters, t_s, hand_prediction_s, image_size = detection.image_size)
