class CameraTrackingServicer(hand_tracking_pb2_grpc.CameraTrackingServicer):
    '''gRPC service that streams camera-based tracking frames.

    Args:
        source: Detection source to poll for results (MediaPipeDetector or
            SyntheticHandSource — anything implementing get_latest_result()).
        stream_rate_hz: Target rate for streaming frames to clients.
        workspace: Workspace mapping config for hand positioning.
            If None, uses the default desk-and-webcam config.
    '''
    
    def __init__(self, source, stream_rate_hz, workspace, include_preview, on_activity_change, head_source, telemetry, identity_observer, frame_observer):
        self._source = source
        self._head_source = head_source
        self._stream_interval = 1 / stream_rate_hz
        self._workspace = workspace
        self._frame_observer = frame_observer
        if include_preview:
            include_preview
        self._include_preview = hasattr(source, 'get_preview')
        self._processor = TrackingFrameProcessor(workspace = workspace, include_head = head_source is not None, telemetry = telemetry, identity_observer = identity_observer)
        self._on_activity_change = on_activity_change
        self._client_count = 0
        self._client_count_lock = threading.Lock()

    
    def StreamFrames(self, request, context):
        '''Server-streaming RPC: continuously yield TrackingFrame messages.'''
        logger.info('Client connected to StreamFrames')
        self._notify_activity_change(delta = 1)
        frame_index = 0
        last_hand_key = None
        last_head_key = None
